mapper.select:
SELECT id, post_id, image_url, sort_order, cover_image, created_at
FROM item_image WHERE post_id = #{postId}
ORDER BY cover_image DESC, sort_order, id

mapper.update:
UPDATE item_image SET cover_image = 1
WHERE id = (
    SELECT id FROM (
        SELECT id FROM item_image WHERE post_id = #{postId}
        ORDER BY sort_order, id LIMIT 1
    ) candidate
)
